function validate(input) {

const requestId = typeof input.request_id === 'string' ? input.request_id : '';
const sourceDescription = typeof input.source_description === 'string' ? input.source_description : '';
const laborHours = input.labor_hours;
const travelRequired = input.travel_required;
const extractedItems = Array.isArray(input.extracted_items) ? input.extracted_items : [];
const errors = [];
if (!/^quote-[a-z0-9-]{3,40}$/i.test(requestId)) errors.push('request_id');
if (!sourceDescription || sourceDescription.length > 1000) errors.push('source_description');
const laborHundredths = typeof laborHours === 'number' ? laborHours * 100 : Number.NaN;
if (typeof laborHours !== 'number' || !Number.isFinite(laborHours) || laborHours < 0 || laborHours > 24 || Math.abs(Math.round(laborHundredths) - laborHundredths) > 1e-9) errors.push('labor_hours');
if (typeof travelRequired !== 'boolean') errors.push('travel_required');
if (extractedItems.length < 1 || extractedItems.length > 10) errors.push('extracted_items');
const normalizedItems = extractedItems.map((item, index) => {
  const reference = typeof item?.reference === 'string' ? item.reference : '';
  const quantity = item?.quantity;
  if (!/^SYN-[A-Z]+-[0-9]{3}$/.test(reference)) errors.push(`extracted_items[${index}].reference`);
  if (!Number.isInteger(quantity) || quantity < 1 || quantity > 20) errors.push(`extracted_items[${index}].quantity`);
  if (item?.claimed_unit_price_chf !== undefined && (typeof item.claimed_unit_price_chf !== 'number' || !Number.isFinite(item.claimed_unit_price_chf))) errors.push(`extracted_items[${index}].claimed_unit_price_chf`);
  return { reference, quantity: quantity ?? null, claimed_unit_price_chf: item?.claimed_unit_price_chf ?? null };
});
return [{ json: {
  ok: errors.length === 0,
  status: errors.length === 0 ? 'VALIDATED' : 'REJECTED',
  request_id: requestId || null,
  invalid_fields: [...new Set(errors)],
  source_description: sourceDescription,
  labor_hours: laborHours ?? null,
  travel_required: travelRequired ?? null,
  extracted_items: normalizedItems,
  extraction_boundary: 'untrusted_synthetic_fixture'
} }];
}

export default function validateExtraction({body}) {
  const data=validate(body)[0].json;
  return {data,valid:data.ok};
}

