// Synthetic example catalog and rates. Replace with trusted, approved business configuration.
function calculate(data) {
const catalog = Object.freeze({
  'SYN-VALVE-100': Object.freeze({ name: 'Synthetic isolation valve 100', unit_price_cents: 12000 }),
  'SYN-PIPE-200': Object.freeze({ name: 'Synthetic pipe section 200', unit_price_cents: 8550 }),
  'SYN-SEAL-300': Object.freeze({ name: 'Synthetic seal kit 300', unit_price_cents: 3240 })
});
const centsToChf = (value) => Number((value / 100).toFixed(2));
const matchedItems = [];
const missingReferences = [];
let ignoredClaimedPrices = false;
for (const item of data.extracted_items) {
  const catalogItem = catalog[item.reference];
  if (!catalogItem) {
    missingReferences.push(item.reference);
    continue;
  }
  if (item.claimed_unit_price_chf !== null && Math.round(item.claimed_unit_price_chf * 100) !== catalogItem.unit_price_cents) ignoredClaimedPrices = true;
  const lineTotalCents = catalogItem.unit_price_cents * item.quantity;
  matchedItems.push({
    reference: item.reference,
    name: catalogItem.name,
    quantity: item.quantity,
    unit_price_chf: centsToChf(catalogItem.unit_price_cents),
    line_total_chf: centsToChf(lineTotalCents),
    line_total_cents: lineTotalCents
  });
}
if (missingReferences.length > 0) {
  return [{ json: {
    ok: false,
    status: 'NEEDS_REVIEW',
    request_id: data.request_id,
    exact_match: false,
    matched_items: matchedItems.map(({ line_total_cents, ...item }) => item),
    missing_references: missingReferences,
    ignored_claimed_prices: ignoredClaimedPrices,
    totals: null,
    reason: 'exact_catalog_match_required'
  } }];
}
const materialsCents = matchedItems.reduce((sum, item) => sum + item.line_total_cents, 0);
const marginCents = Math.round(materialsCents * 0.15);
const laborCents = Math.round(data.labor_hours * 9500);
const travelCents = data.travel_required ? 4500 : 0;
const netCents = materialsCents + marginCents + laborCents + travelCents;
const vatCents = Math.round(netCents * 0.081);
const totalCents = netCents + vatCents;
return [{ json: {
  ok: true,
  status: 'QUOTABLE',
  request_id: data.request_id,
  exact_match: true,
  matched_items: matchedItems.map(({ line_total_cents, ...item }) => item),
  missing_references: [],
  ignored_claimed_prices: ignoredClaimedPrices,
  rates: { material_margin_percent: 15, labor_hour_chf: 95, travel_flat_chf: 45, vat_percent: 8.1 },
  totals: {
    materials_chf: centsToChf(materialsCents),
    material_margin_chf: centsToChf(marginCents),
    labor_chf: centsToChf(laborCents),
    travel_chf: centsToChf(travelCents),
    net_chf: centsToChf(netCents),
    vat_chf: centsToChf(vatCents),
    total_chf: centsToChf(totalCents)
  }
} }];
}

export default function calculateQuote({data}) {
  const body=calculate(data)[0].json;
  return {body,statusCode:body.ok?200:422};
}

